namespace ghidra.app.plugin.core.decompiler.taint.actions;



using docking.action;
using docking.action;
using ghidra.app.decompiler;
using ghidra.app.plugin.core.decompile;
using ghidra.app.plugin.core.decompiler.taint;
using ghidra.app.plugin.core.decompiler.taint.TaintState;
